function speakLine(text,subtitle,lang='en-US',onDone){ listening=true; marker.visible=false; targetLabel.style.display='none'; taskEl.textContent='Задание: дослушай сообщение'; setMessage(subtitle, 20000); audio.duck(.12); const u=new SpeechSynthesisUtterance(text); u.lang=lang; u.rate=.92; u.pitch=.62; let voices=speechSynthesis.getVoices?.()||[]; let preferred=voices.find(v=>v.lang.startsWith('en'))||voices[0]; if(preferred) u.voice=preferred; u.onend=()=>{ audio.unduck(); listening=false; msg.style.opacity=0; onDone?.(); }; u.onerror=()=>{ audio.unduck(); listening=false; msg.style.opacity=0; setMessage('Сообщение оборвалось.'); onDone?.(); }; speechSynthesis.cancel(); speechSynthesis.speak(u); }

