function animateCustomer(dt){if(!customerWalk)return;let {npc,path,i}=customerWalk;let [x,z]=path[i];let dx=x-npc.position.x,dz=z-npc.position.z,d=Math.hypot(dx,dz);if(d<.06){customerWalk.i++;if(customerWalk.i>=path.length){customerWalk=null;npc.rotation.y=0;for(const l of [...npc.userData.legs,...npc.userData.arms])l.rotation.x=0;}return;}npc.rotation.y=Math.atan2(dx,dz);npc.position.x+=dx/d*Math.min(d,dt*1.45);npc.position.z+=dz/d*Math.min(d,dt*1.45);npc.userData.legs.forEach((l,j)=>l.rotation.x=Math.sin(performance.now()*.009+j*Math.PI)*.38);npc.userData.arms.forEach((l,j)=>l.rotation.x=-Math.sin(performance.now()*.009+j*Math.PI)*.26);}
